#include "engine/entities/entity_registry.hpp"
namespace origin{EntityId EntityRegistry::create(std::string n,Material m,const RigidBody&b){auto id=next_++;e_.push_back({id,std::move(n),b,m,true});ix_[id]=e_.size()-1;return id;}bool EntityRegistry::insert_restored(const Entity&x){if(!x.id||ix_.contains(x.id))return false;e_.push_back(x);ix_[x.id]=e_.size()-1;next_=std::max(next_,x.id+1);return true;}}
